  Fsc = za(j1, j4) * za(j2, j3) * zab2(j1,j2,j3,j5) / (std::pow(za(j1, j3), 3) * s123)
        * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123)
        + half * za(j4, j1) * std::pow(zb(j1, j3), 2) * za(j2, j3) * zab2(j1,j2,j3,j5)
        / (za(j1, j3) * s123) * L1(-s123, -s(j2, j3)) / std::pow(s(j2, j3), 2)
